INSERT INTO `stakeholder_involvement` VALUES (1,2,'sadfasdf','2025-06-15 09:52:31','2025-06-15 09:52:31'),(2,5,'╪»╪▒ ┘å╪╕╪º┘àΓÇî┘ç╪º█î ╪ó┘à┘ê╪▓╪┤█î ╪¿╪º ┌⌐█î┘ü█î╪¬╪î ┘å┘é╪┤ ╪░█î┘å┘ü╪╣╪º┘å (╪º╪╣┘à ╪º╪▓ ╪┤╪º┌»╪▒╪»╪º┘å╪î ┘à╪»╪▒╪│╪º┘å╪î ┌⌐╪º╪▒┌⌐┘å╪º┘å ╪º╪»╪º╪▒█î╪î ┌⌐╪º╪▒┘ü╪▒┘à╪º█î╪º┘å╪î ╪«╪º┘å┘ê╪º╪»┘çΓÇî┘ç╪º╪î ┘å┘ç╪º╪»┘ç╪º█î ╪»┘ê┘ä╪¬█î╪î ╪┤╪▒┌⌐╪º█î ╪º╪¼╪¬┘à╪º╪╣█î ┘ê ╪│╪º╪▓┘à╪º┘åΓÇî┘ç╪º█î ╪║█î╪▒╪»┘ê┘ä╪¬█î) ╪»╪▒ ╪¿┘ç╪¿┘ê╪» ╪╣┘à┘ä┌⌐╪▒╪» ┘ê ╪º╪½╪▒╪¿╪«╪┤█î ┘ü╪╣╪º┘ä█î╪¬ΓÇî┘ç╪º█î ╪ó┘à┘ê╪▓╪┤█î ╪¿╪│█î╪º╪▒ ╪º╪│╪º╪│█î ╪º╪│╪¬. ╪»╪«█î┘äΓÇî╪│╪º╪▓█î ┘ü╪╣╪º┘ä ╪░█î┘å┘ü╪╣╪º┘å ┘à█îΓÇî╪¬┘ê╪º┘å╪» ┘à┘å╪¼╪▒ ╪¿┘ç ╪º┘ü╪▓╪º█î╪┤ ╪┤┘ü╪º┘ü█î╪¬╪î ┘╛╪º╪│╪«ΓÇî┌»┘ê█î█î╪î ╪º┘å╪│╪¼╪º┘à ╪¿╪▒┘å╪º┘à┘çΓÇî┘ç╪º╪î ┘ê ╪º█î╪¼╪º╪» ╪º╪╣╪¬┘à╪º╪» ╪╣┘à┘ê┘à█î ┘å╪│╪¿╪¬ ╪¿┘ç ╪╣┘à┘ä┌⌐╪▒╪» ┘à╪▒┌⌐╪▓ ┌»╪▒╪»╪».\n\n┘à╪▒┌⌐╪▓ ╪ó┘à┘ê╪▓╪┤█î ┘à┌⌐┘ä┘ü ╪º╪│╪¬ ╪¿╪º ╪º█î╪¼╪º╪» ╪│╪º╪«╪¬╪º╪▒┘ç╪º█î ┘à╪┤╪«╪╡ (┘à╪º┘å┘å╪» ┌⌐┘à█î╪¬┘çΓÇî┘ç╪º╪î ╪¼┘ä╪│╪º╪¬ ┘à╪┤┘ê╪▒╪¬█î╪î ┘å╪╕╪▒╪│┘å╪¼█îΓÇî┘ç╪º╪î ┌»╪▒┘ê┘çΓÇî┘ç╪º█î ┌⌐╪º╪▒█î ┘ê ┘à╪┤╪º╪▒┌⌐╪¬ ╪»╪▒ ╪º╪▒╪▓█î╪º╪¿█îΓÇî┘ç╪º)╪î ╪▓┘à█î┘å┘çΓÇî ┘à╪┤╪º╪▒┌⌐╪¬ ┘à╪ñ╪½╪▒ ╪░█î┘å┘ü╪╣╪º┘å ╪▒╪º ╪»╪▒ ╪¬┘à╪º┘à ╪│╪╖┘ê╪¡ ┘ü╪▒╪º┘ç┘à ╪│╪º╪▓╪» ┘ê ┘å╪╕╪▒╪º╪¬╪î ┘å█î╪º╪▓┘ç╪º ┘ê ┘╛█î╪┤┘å┘ç╪º╪»╪º╪¬ ╪ó┘å╪º┘å ╪▒╪º ╪»╪▒ ╪¬╪╡┘à█î┘àΓÇî┌»█î╪▒█îΓÇî┘ç╪º ┘à╪»┘å╪╕╪▒ ┘é╪▒╪º╪▒ ╪»┘ç╪».\n\n','2025-06-22 11:17:14','2025-06-22 11:17:14'),(3,9,'╪░█î┘å┘ü╪╣╪º┘å ╪»╪º╪«┘ä█î:\n\n┘à╪¡╪╡┘ä╪º┘å: ╪º╪│╪¬┘ü╪º╪»┘çΓÇî┌⌐┘å┘å╪»┘çΓÇî█î ╪º╪╡┘ä█î ╪º╪▓ ╪«╪»┘à╪º╪¬ ╪ó┘à┘ê╪▓╪┤█î.\n\n╪º╪│╪¬╪º╪»╪º┘å ┘ê ╪ó┘à┘ê╪▓┌»╪º╪▒╪º┘å: ╪º╪▒╪º█î┘çΓÇî╪»┘ç┘å╪»┌»╪º┘å ╪«╪»┘à╪º╪¬ ╪ó┘à┘ê╪▓╪┤█î.\n\n┘à╪»█î╪▒╪º┘å ┘ê ┌⌐╪º╪▒┘à┘å╪»╪º┘å: ╪▒┘ç╪¿╪▒█î ┘ê ┘à╪»█î╪▒█î╪¬ ┘ü╪╣╪º┘ä█î╪¬ΓÇî┘ç╪º█î ┘à╪▒┌⌐╪▓.\n\n╪┤┘ê╪▒╪º┘ç╪º█î ╪╣┘ä┘à█î █î╪º ┌⌐┘à█î╪¬┘çΓÇî┘ç╪º█î ╪¬╪╢┘à█î┘å ┌⌐█î┘ü█î╪¬.\n\n╪░█î┘å┘ü╪╣╪º┘å ╪«╪º╪▒╪¼█î:\n\n┘ê╪º┘ä╪»█î┘å █î╪º ╪«╪º┘å┘ê╪º╪»┘çΓÇî┘ç╪º█î ┘à╪¡╪╡┘ä╪º┘å: ╪¿┘çΓÇî┘ê█î┌ÿ┘ç ╪»╪▒ ╪│╪╖┘ê╪¡ ┘╛╪º█î█î┘åΓÇî╪¬╪▒ ╪ó┘à┘ê╪▓╪┤█î.\n\n╪º╪»╪º╪▒┘ç ╪¬╪╣┘ä█î┘à╪º╪¬ ╪¬╪«┘å█î┌⌐█î ┘ê ┘à╪│┘ä┌⌐█î / ┘ê╪▓╪º╪▒╪¬ ┘à╪╣╪º╪▒┘ü █î╪º ╪¬╪¡╪╡█î┘ä╪º╪¬ ╪╣╪º┘ä█î: ╪¬┘å╪╕█î┘àΓÇî┌⌐┘å┘å╪»┌»╪º┘å ┘à┘é╪▒╪▒╪º╪¬ ┘ê ┘å╪╕╪º╪▒╪¬ΓÇî┌⌐┘å┘å╪»┘çΓÇî┘ç╪º.\n\n╪╡┘å╪╣╪¬ ┘ê ╪¿╪º╪▓╪º╪▒ ┌⌐╪º╪▒: ┌⌐╪º╪▒┘ü╪▒┘à╪º█î╪º┘å ╪¿╪º┘ä┘é┘ê┘ç ┌⌐┘ç ╪«┘ê╪º┘ç╪º┘å ┘å█î╪▒┘ê█î ╪¿╪┤╪▒█î ┘à╪º┘ç╪▒ ╪º┘å╪».\n\n┘å┘ç╪º╪»┘ç╪º█î ╪¬┘à┘ê█î┘äΓÇî┌⌐┘å┘å╪»┘ç: ┘à╪º┘å┘å╪» ┘å┘ç╪º╪»┘ç╪º█î ╪¿█î┘åΓÇî╪º┘ä┘à┘ä┘ä█î █î╪º NGO┘ç╪º.\n\n╪¼╪º┘à╪╣┘ç ┘à╪»┘å█î ┘ê ┘à╪▒╪»┘à ┘à╪¡┘ä.','2025-06-24 04:43:26','2025-06-24 04:43:26'),(4,19,'asdfasdfasdfasdfasdfasdfasdfasdfasdfasdfsadfasdfasdfasdf','2025-07-27 10:12:30','2025-07-27 10:12:30');
