DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `students` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `name` varchar(255) NOT NULL,
  `newEnrollments` int NOT NULL,
  `totalStudents` int NOT NULL,
  `graduationCycles` int NOT NULL,
  `establishmentYear` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `userId` (`userId`),
  CONSTRAINT `students_ibfk_1` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `students_chk_1` CHECK ((`newEnrollments` >= 0)),
  CONSTRAINT `students_chk_2` CHECK ((`totalStudents` >= 0)),
  CONSTRAINT `students_chk_3` CHECK ((`graduationCycles` >= 0)),
  CONSTRAINT `students_chk_4` CHECK (((`establishmentYear` >= 1300) and (`establishmentYear` <= 1500)))
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
